UML = """classDiagram
    class Team {
        +String name
        +add(player) void
        +remove(player) void
        +disband() void
    }
    class Player {
        +String name
    }
    Team "1" o-- "*" Player : groups
"""


class Player:
    def __init__(self, name):
        self.name = name
        self.team = None


class Team:
    def __init__(self, name):
        self.name = name
        self._players = []

    @property
    def players(self):
        return tuple(self._players)

    def add(self, player):
        if player.team is not None:
            raise ValueError("Already in a team")
        self._players.append(player)
        player.team = self

    def remove(self, player):
        if player not in self._players:
            raise ValueError("Not in this team")
        self._players.remove(player)
        player.team = None

    def disband(self):
        for player in self._players:
            player.team = None
        self._players.clear()
